const MAX_JOBS_PER_RUN = 12;
const sources = [
  {
    name: 'n8n Community Jobs',
    feedUrl: 'https://community.n8n.io/c/jobs/12.rss',
    sourceType: 'rss'
  },
  {
    name: 'Freelancer - n8n automation',
    feedUrl: 'https://www.freelancer.com/rss.xml?keyword=n8n%20automation',
    sourceType: 'rss'
  },
  {
    name: 'Freelancer - Google Sheets automation',
    feedUrl: 'https://www.freelancer.com/rss.xml?keyword=google%20sheets%20automation',
    sourceType: 'rss'
  },
  {
    name: 'Freelancer - Zapier Google Sheets',
    feedUrl: 'https://www.freelancer.com/rss.xml?keyword=zapier%20google%20sheets',
    sourceType: 'rss'
  },
  {
    name: 'Freelancer - OpenAI Google Sheets',
    feedUrl: 'https://www.freelancer.com/rss.xml?keyword=openai%20google%20sheets',
    sourceType: 'rss'
  },
  {
    name: 'Freelancer - workflow automation',
    feedUrl: 'https://www.freelancer.com/rss.xml?keyword=workflow%20automation',
    sourceType: 'rss'
  }
];

const positiveTerms = [
  'n8n', 'zapier', 'make.com', 'make ', 'google sheets', 'spreadsheet', 'openai',
  'chatgpt', 'ai automation', 'workflow automation', 'automation', 'lead capture',
  'lead management', 'email classification', 'gmail', 'slack', 'crm', 'webhook',
  'api integration', 'daily report', 'report automation', 'data cleanup', 'ai summary'
];

const hardRejectTerms = [
  'machine learning model', 'model training', 'deep learning', 'computer vision',
  'full stack', 'full-stack', 'react developer', 'next.js', 'kubernetes', 'devops',
  'aws infrastructure', 'docker expert', 'mobile app', 'ios app', 'android app',
  'blockchain', 'solidity', 'trading bot', 'voice agent', 'vapi', 'twilio sip'
];

const decodeEntities = (text) => String(text || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&#x2F;/g, '/')
  .trim();

const stripHtml = (text) => decodeEntities(text)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const getTag = (block, tag) => {
  const match = block.match(new RegExp(`<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return match ? decodeEntities(match[1]) : '';
};

const getAtomLink = (block) => {
  const href = block.match(/<link[^>]+href=["']([^"']+)["'][^>]*>/i);
  if (href) return decodeEntities(href[1]);
  return getTag(block, 'link');
};

const normalizeUrl = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw);
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'].forEach((key) => url.searchParams.delete(key));
    return url.toString();
  } catch {
    return raw;
  }
};

const parseRss = (xml, source) => {
  const blocks = xml.match(/<item[\s\S]*?<\/item>|<entry[\s\S]*?<\/entry>/gi) || [];
  return blocks.map((block) => {
    const title = stripHtml(getTag(block, 'title'));
    const link = normalizeUrl(getAtomLink(block));
    const description = stripHtml(
      getTag(block, 'description') ||
      getTag(block, 'content:encoded') ||
      getTag(block, 'summary') ||
      getTag(block, 'content')
    ).slice(0, 30000);
    const postedDate = stripHtml(getTag(block, 'pubDate') || getTag(block, 'updated') || getTag(block, 'published'));
    return {
      source: source.name,
      sourceFeedUrl: source.feedUrl,
      jobTitle: title,
      jobLink: link,
      rawRequirement: description || title,
      postedDate,
      requirementSource: 'auto_rss',
      fetchNote: ''
    };
  }).filter((job) => job.jobTitle && job.jobLink);
};

const existingLinks = new Set(
  $input.all()
    .map((item) => normalizeUrl(item.json['Job Link'] || item.json.jobLink || item.json.link || ''))
    .filter(Boolean)
);
const seenThisRun = new Set(existingLinks);
const candidates = [];

for (const source of sources) {
  try {
    const response = await fetch(source.feedUrl, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; AI-Side-Job-Radar/1.0)'
      }
    });
    if (!response.ok) continue;
    const xml = await response.text();
    for (const job of parseRss(xml, source)) {
      const normalizedLink = normalizeUrl(job.jobLink);
      if (!normalizedLink || seenThisRun.has(normalizedLink)) continue;
      const haystack = `${job.jobTitle} ${job.rawRequirement}`.toLowerCase();
      const hardRejected = hardRejectTerms.some((term) => haystack.includes(term));
      if (hardRejected) continue;
      const matchCount = positiveTerms.filter((term) => haystack.includes(term)).length;
      if (matchCount === 0) continue;
      seenThisRun.add(normalizedLink);
      candidates.push({
        ...job,
        jobLink: normalizedLink,
        keywordMatchCount: matchCount,
        scrapedAt: new Date().toISOString()
      });
    }
  } catch (error) {
    // Keep the workflow resilient. Failed sources are skipped for this run.
  }
}

candidates.sort((a, b) => {
  const scoreDiff = b.keywordMatchCount - a.keywordMatchCount;
  if (scoreDiff) return scoreDiff;
  return String(b.postedDate || '').localeCompare(String(a.postedDate || ''));
});

return candidates.slice(0, MAX_JOBS_PER_RUN).map((job) => ({ json: job }));

const OPENAI_API_KEY = 'REPLACE_WITH_OPENAI_API_KEY';
const OPENAI_MODEL = 'gpt-4o-mini';
const APPLY_PRIORITIES = new Set(['Apply Now', 'Build Demo First', 'Save for Learning', 'Skip']);
const CAN_START_VALUES = new Set(['Yes', 'Maybe', 'No']);

if (!OPENAI_API_KEY || OPENAI_API_KEY.includes('REPLACE_WITH_')) {
  throw new Error('Set OPENAI_API_KEY inside the Analyze And Format Rows node before running this workflow.');
}

const profile = {
  targetMarket: 'English market',
  availableTime: '2 hours/day',
  preferredWork: 'AI automation and AI tool setup',
  toolsKnown: ['Cursor', 'OpenAI API', 'Feishu', 'n8n', 'Google Sheets'],
  codingLevel: 'beginner Python',
  meetingPreference: 'async-first, limited meetings',
  portfolio: 'no public portfolio yet',
  bestFitProjects: ['Google Sheets automation', 'n8n workflows', 'lead capture', 'email classification', 'AI summaries', 'daily reporting'],
  avoidProjects: ['machine learning training', 'full-stack SaaS', 'complex backend systems', 'heavy meetings', 'production infrastructure ownership']
};

const score = (value) => {
  const number = Number(value);
  if (Number.isNaN(number)) return 0;
  return Math.max(1, Math.min(10, Math.round(number)));
};

const parseAnalysis = (text) => {
  const match = String(text || '').match(/\{[\s\S]*\}/);
  if (!match) throw new Error('OpenAI response did not contain JSON: ' + text);
  return JSON.parse(match[0]);
};

const buildPrompt = (job) => `You are an opportunity analyst for a beginner AI automation freelancer.

Goal: decide whether this side job is suitable for Kathy, and produce useful next actions for a Google Sheet.

Kathy profile:
${JSON.stringify(profile, null, 2)}

Job post data:
${JSON.stringify(job, null, 2)}

Score rules:
- yourMatchScore: 1-10. Current capability match.
- aiLeverageScore: 1-10. How much OpenAI/n8n/Sheets can help delivery.
- asyncFitScore: 1-10. Higher means less meeting dependency.
- learningValue: 1-10. Higher means useful skill compounding.
- deliveryRisk: 1-10. Higher means more risk, ambiguity, hidden complexity, or maintenance burden.
- starterFitScore: 1-10. Higher means Kathy can realistically start now with her current tools and beginner Python.

Starter filter rules:
- canStartNow must be one of: Yes, Maybe, No.
- applyPriority must be one of: Apply Now, Build Demo First, Save for Learning, Skip.
- Mark canStartNow as Yes only when the job is narrow, async-friendly, has a clear deliverable, can be built with Google Sheets/n8n/Zapier/Make/OpenAI, and does not require advanced backend, ML, production infrastructure, frequent meetings, or a strong existing portfolio.
- Mark Build Demo First when the job is suitable but Kathy needs one small proof/demo before applying confidently.
- Mark Save for Learning when it teaches useful skills but is too risky to apply now.
- Mark Skip when the project is vague, too broad, meeting-heavy, full-stack, ML/model-training, infrastructure-heavy, or asks for expert ownership.

Recommendation standard:
- Favor narrow workflows, clear deliverables, Google Sheets, n8n, Zapier/Make, AI classification, AI summaries, lead capture, reporting, and status tracking.
- Penalize full-stack apps, ML training, custom backend infrastructure, self-hosted production ownership, complex agents, frequent meetings, and vague enterprise transformation.
- Be direct. If the job is not suitable, say so in nextAction.

Extraction requirements:
- recruiterContact: extract recruiter/client contact details if present, such as name, email, website, Slack/Discord, Telegram, booking link, or Freelancer/n8n profile info. If not present, return "Not provided".
- learningResourceLinks: provide 2-4 directly useful learning URLs for the required skills. Prefer official docs and practical templates.
- missingProof: what Kathy would need to show before applying, such as "n8n lead capture demo". If nothing is needed, return "None".
- firstTwoHourPrep: one concrete prep task Kathy can finish in 2 hours before applying or building a demo.
- starterFitReason: explain in one sentence why this is or is not starter-friendly.

Return only valid JSON. Do not wrap in markdown. Do not include comments.
Use exactly these keys:
recruiterContact, jobCategory, realNeed, deliverable, requiredTools, requiredSkills, yourMatchScore, aiLeverageScore, asyncFitScore, learningValue, deliveryRisk, starterFitScore, canStartNow, applyPriority, starterFitReason, missingProof, firstTwoHourPrep, recommendedSkillset, learningResource, learningResourceLinks, knowledgeBaseTopic, bestPractice, suggestedPitch, nextAction, notes

For arrays, return short comma-separated strings instead of JSON arrays.
For suggestedPitch, write a concise English proposal under 140 words.`;

const rows = [];

for (const item of $input.all()) {
  const job = item.json;
  const response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: OPENAI_MODEL,
      max_tokens: 1800,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: 'Return only valid JSON.' },
        { role: 'user', content: buildPrompt(job) }
      ]
    })
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`OpenAI request failed ${response.status}: ${errorText}`);
  }

  const payload = await response.json();
  const analysis = parseAnalysis(payload.choices?.[0]?.message?.content || '');
  const yourMatchScore = score(analysis.yourMatchScore);
  const aiLeverageScore = score(analysis.aiLeverageScore);
  const asyncFitScore = score(analysis.asyncFitScore);
  const learningValue = score(analysis.learningValue);
  const deliveryRisk = score(analysis.deliveryRisk);
  const starterFitScore = score(analysis.starterFitScore);
  const opportunityScore = yourMatchScore + aiLeverageScore + asyncFitScore + learningValue - deliveryRisk;
  const applyPriority = APPLY_PRIORITIES.has(analysis.applyPriority) ? analysis.applyPriority : 'Save for Learning';
  const canStartNow = CAN_START_VALUES.has(analysis.canStartNow) ? analysis.canStartNow : 'Maybe';
  const statusByPriority = {
    'Apply Now': 'Shortlisted',
    'Build Demo First': 'Needs Demo',
    'Save for Learning': 'Learning',
    'Skip': 'Archived'
  };
  const notes = [
    analysis.notes || '',
    job.postedDate ? `Posted: ${job.postedDate}` : '',
    job.keywordMatchCount ? `Keyword matches: ${job.keywordMatchCount}` : ''
  ].filter(Boolean).join(' | ');

  rows.push({
    json: {
      'Date Added': new Date().toISOString().slice(0, 10),
      'Source': job.source || '',
      'Job Title': job.jobTitle || '',
      'Job Link': job.jobLink || '',
      'Recruiter Contact': analysis.recruiterContact || 'Not provided',
      'Raw Requirement': job.rawRequirement || '',
      'Full Job Requirement': job.rawRequirement || '',
      'Job Category': analysis.jobCategory || '',
      'Real Need': analysis.realNeed || '',
      'Deliverable': analysis.deliverable || '',
      'Required Tools': analysis.requiredTools || '',
      'Required Skills': analysis.requiredSkills || '',
      'Your Match Score': yourMatchScore,
      'AI Leverage Score': aiLeverageScore,
      'Async Fit Score': asyncFitScore,
      'Learning Value': learningValue,
      'Delivery Risk': deliveryRisk,
      'Opportunity Score': opportunityScore,
      'Starter Fit Score': starterFitScore,
      'Can Start Now': canStartNow,
      'Apply Priority': applyPriority,
      'Starter Fit Reason': analysis.starterFitReason || '',
      'Missing Proof': analysis.missingProof || '',
      'First 2-Hour Prep': analysis.firstTwoHourPrep || '',
      'Recommended Skillset': analysis.recommendedSkillset || '',
      'Learning Resource': analysis.learningResource || '',
      'Learning Resource Links': analysis.learningResourceLinks || '',
      'Knowledge Base Topic': analysis.knowledgeBaseTopic || '',
      'Best Practice': analysis.bestPractice || '',
      'Suggested Pitch': analysis.suggestedPitch || '',
      'Next Action': analysis.nextAction || '',
      'Status': statusByPriority[applyPriority] || 'Learning',
      'Notes': notes
    }
  });

  await new Promise((resolve) => setTimeout(resolve, 250));
}

return rows;
